class Employee {
    protected String empId;
    protected String name;
    protected double baseSalary;

    public Employee(String empId, String name, double baseSalary) {
        if (baseSalary < 0) throw new IllegalArgumentException("Salary cannot be negative");
        this.empId = empId;
        this.name = name;
        this.baseSalary = baseSalary;
    }

    public double calculateTotalCompensation() {
        return this.baseSalary;
    }

    public void printProfile() {
        System.out.println("[" + empId + "] " + name + " | Base Salary: $" + baseSalary);
    }
}

class Developer extends Employee {
    private String primaryLanguage;
    private int bugsResolved;

    public Developer(String id, String name, double salary, String lang) {
        super(id, name, salary);
        this.primaryLanguage = lang;
        this.bugsResolved = 0;
    }

    public void resolveBugs(int count) {
        this.bugsResolved += count;
        System.out.println(name + " resolved " + count + " bugs in " + primaryLanguage);
    }

    public double calculateTotalCompensation() {
        // Bonus: $100 per resolved bug
        return baseSalary + (bugsResolved * 100.0);
    }
}

class Manager extends Employee {
    protected int teamSize;
    protected double teamBudget;

    public Manager(String id, String name, double salary, int teamSize, double budget) {
        super(id, name, salary);
        this.teamSize = teamSize;
        this.teamBudget = budget;
    }

    public double calculateTotalCompensation() {
        // Bonus: $2,000 per team member
        return baseSalary + (teamSize * 2000.0);
    }
}

class Director extends Manager {
    private int stockUnits;

    public Director(String id, String name, double salary, int teamSize, double budget, int stock) {
        super(id, name, salary, teamSize, budget);
        this.stockUnits = stock;
    }

    public double calculateTotalCompensation() {
        // Executive bonus: Manager team bonus + $50 per stock unit
        return super.calculateTotalCompensation() + (stockUnits * 50.0);
    }

    public void printExecutiveBrief() {
        printProfile();
        System.out.println("Executive Oversight: " + teamSize + " employees | Budget: $" + teamBudget + " | Stock: " + stockUnits + " RSUs");
        System.out.println("Total Executive Package: $" + calculateTotalCompensation());
    }
}

public class CorporateHierarchyDemo {
    public static void main(String[] args) {
        Developer dev = new Developer("DEV-101", "Alex Chen", 95000.0, "Java");
        dev.resolveBugs(15);
        dev.printProfile();
        System.out.println("Developer Package: $" + dev.calculateTotalCompensation());

        Director dir = new Director("DIR-01", "Sophia Vance", 180000.0, 24, 1500000.0, 1000);
        dir.printExecutiveBrief();
    }
}

