class Employee {
    protected String name;
    protected double baseSalary;
    public Employee(String name, double salary) {
        this.name = name;
        this.baseSalary = salary;
    }
    public double calculateTotalCompensation() {
        return baseSalary;
    }
}

class Developer extends Employee {
    private int bonus;
    public Developer(String name, double salary, int bonus) {
        super(name, salary);
        this.bonus = bonus;
    }
    public double calculateTotalCompensation() {
        return baseSalary + bonus;
    }
}

class Manager extends Employee {
    private int reports;
    public Manager(String name, double salary, int reports) {
        super(name, salary);
        this.reports = reports;
    }
    public double calculateTotalCompensation() {
        return baseSalary + (reports * 2000.0);
    }
}

class Director extends Manager {
    private double equityBonus;
    public Director(String name, double salary, int reports, double equityBonus) {
        super(name, salary, reports);
        this.equityBonus = equityBonus;
    }
    public double calculateTotalCompensation() {
        return super.calculateTotalCompensation() + equityBonus;
    }
}

public class Main {
    public static void main(String[] args) {
        Employee[] staff = new Employee[] {
            new Developer("Dave", 90000.0, 5000),
            new Manager("Alice", 120000.0, 5),   // 120000 + 10000 = 130000
            new Director("Carol", 150000.0, 10, 20000.0) // 150000 + 20000 + 20000 = 190000
        };

        double total = 0;
        for (Employee e : staff) {
            total += e.calculateTotalCompensation();
        }

        System.out.println("Processed Payroll for " + staff.length + " employees.");
        System.out.println("Total Enterprise Payroll: $" + total);
    }
}
